<div class="auth-box"><h2 class="fw-bold mb-4">Tạo tài khoản</h2><form method="post" action="/register"><input class="form-control mb-3" name="name" placeholder="Họ tên" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" type="password" name="password" minlength="8" placeholder="Mật khẩu (ít nhất 8 ký tự)" required><button class="btn btn-warning w-100">Đăng ký</button></form><p class="mt-3">Đã có tài khoản? <a href="/login">Đăng nhập</a></p></div>
